	static int floorFinder(String s) {
		int floor = 0;
			
	
		char[] arr = s.toCharArray();
		for(int i =0; i<arr.length;i++) {
			
			if (arr[i]=='(') {
				floor++;
			}
		
			else {
				floor--;
			}
			
		}
		
		return floor;
		
	}
	
	static int basementFinder(String s) {
		int floor = 0;
		int basementEntry = 0;	
		boolean firstEntry = true;
		char[] arr = s.toCharArray();
		for(int i =0; i<arr.length;i++) {
			
			if (arr[i]=='(') {
				floor++;
			}
			
			
			if (arr[i]==')') {
				floor--;
			}
			if (floor<0 && firstEntry==true ) {
				basementEntry = i+1;
				firstEntry = false;
			}
		}
		
		return basementEntry;
		
	}
